    step("sequence", "workbench", "Test the crew's stop button", "Run the tide drive at its test load, press STOP, and inspect the still shaft before resetting.", line("Edda", "It stops. It stays stopped. I can check both with my own eyes."), { challenge: sequence("Witness a complete stop test.", ["Press STOP", "Run the small test load", "Inspect the still shaft", "Reset by hand"], [1, 0, 2, 3], "Start a test load, stop it, check the shaft is still, then reset. Resetting must never restart the drive by itself.", "The shaft remains still after reset until a keeper chooses START."), evidence: evidence("A witnessed stop test", "The crew ran a test load, stopped it, observed the still shaft, and reset by hand. Reset did not restart the machine."), visual: visual("machine", "STOP means stop", "The workshop drive stays stopped after its control is reset.") }),
    step("deliver", "outlet", "Leave the plans with Edda", "Place the tested drawing and the workshop key at Edda's outlet desk.", line("oren", "The only key stays here. I am taking the copy that anyone else could take."))
