    step("repair", "stores", "Secure the dry clinic boardwalk", "Latch Aven's raised transfer boards into the stone sockets. Check the rail at the last turn.", line("Aven", "The boards are fixed. Bring them one at a time; the ward is ready."), { opensGate: true, visual: visual("bridge", "Dry clinic boardwalk", "A raised, railed path joins the outlying rooms to the lighthouse clinic.") }),
    step("escort", "patient1", "Walk Ina to the lighthouse", "Guide Ina from the first room to the clinic. Keep close through the boardwalk turns.", line("Ina", "A window, and my blanket on the bed. I can rest here."), { to: "clinic" }),
    step("escort", "patient2", "Walk Tem to the lighthouse", "Return for Tem and guide him from the second room to the clinic.", line("Tem", "Put the cup on my right. There. I know this little piece of the room already."), { to: "clinic" }),
    step("escort", "patient3", "Walk Rell to the lighthouse", "Return for Rell and guide them from the third room to the clinic. Keep the letter in its pack.", line("Rell", "Let the letter wait. I want to look at the sea first."), { to: "clinic", visual: visual("shelter", "Three patients received", "Ina, Tem, and Rell are in the clinic with their chosen keepsakes.") }),
    step("deliver", "light", "Give Aven the care handover", "At the lighthouse desk, confirm the patient count, keepsake labels, and the next tide watch with Aven.", line("Aven", "Three patients, three packs, dry walkway checked. I take the next watch. Vale, you can step outside."), { evidence: evidence("Aven's handover", "Aven has received all three patients and their requests, checked the dry path, and accepted the next tide watch.") }),
    step("talk", "garden", "Ask Vale what comes next", "Meet Vale in the small lighthouse garden, beyond the duty desk.", line("Vale", "I would like to travel with you. I would also like to sit here for one minute before we go."), { visual: visual("garden", "A place beyond the ward", "The garden bench is open to a healer whose next watch is covered.") })
