    step("escort", "core", "Return to the listening chamber", "Walk from the quiet core to the return chamber. The final control now waits for a choice instead of issuing an order.", line("iona", "The guard has ended. Let us hear them before we choose what remains."), { to: "return", visual: visual("power", "The guard is quiet", "The central command has ended. The return chamber can hear the stored voices without it.") })
